import { Hono } from "hono";
import type { AppEnv } from "./env";

// Acme Weather. The forecast provider's key comes from the app's Environment
// (c.env.WEATHER_API_KEY); the page says so plainly when it is not set.
type WeatherEnv = AppEnv & { Bindings: { WEATHER_API_KEY?: string } };

export const weather = new Hono<WeatherEnv>();

weather.get("/", (c) => {
  const key = c.env.WEATHER_API_KEY;
  if (!key) return c.json({ configured: false, message: "The forecast key is not set yet." });
  return c.json({ configured: true, city: "Acme City", forecast: "Sunny, 22 degrees", keyLength: key.length });
});

import { Hono } from "hono";
import type { AppEnv } from "./env";
import { oneRoutes } from "./one/connect";
import { weather } from "./weather";

// The app's API. Runtime-neutral Hono: server/worker.ts runs it on Workers,
// api/index.ts on Vercel. Add routes below the One routes.

const app = new Hono<AppEnv>();

app.get("/api/health", (c) => c.json({ ok: true, app: "Acme Weather" }));

// Sign in with One, the grant, and /api/one/health. Do not edit.
app.route("/api/one", oneRoutes);

app.route("/api/weather", weather);

app.notFound((c) => c.json({ error: { code: "not_found", message: `No route for ${c.req.path}` } }, 404));

app.onError((err, c) => {
  console.error(err);
  return c.json({ error: { code: "server_error", message: err.message } }, 500);
});

export default app;

import { useEffect, useState } from "react";
import { AppShell } from "@/components/shell/AppShell";

type Weather = { configured: false; message: string } | { configured: true; city: string; forecast: string };

// Acme Weather: today's forecast, from the provider's key in the app's Environment.
export default function App() {
  const [w, setW] = useState<Weather | null>(null);
  useEffect(() => {
    fetch("/api/weather").then((r) => r.json() as Promise<Weather>).then(setW).catch(() => setW({ configured: false, message: "The forecast did not load." }));
  }, []);
  return (
    <AppShell>
      <div className="mb-8 flex flex-col gap-2">
        <p className="label-caps">Acme Inc</p>
        <h1 className="text-28 font-semibold tracking-tight">Acme Weather</h1>
        <p className="max-w-lg text-15 text-muted-foreground" data-testid="weather">{!w ? "Loading the forecast" : w.configured ? `${w.city}: ${w.forecast}` : w.message}</p>
      </div>
    </AppShell>
  );
}
